import{_ as a,c as t,o as r,aj as o}from"./chunks/framework.BlveriQe.js";const u=JSON.parse('{"title":"Interface: FunctionsAPI","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/FunctionsAPI.md","filePath":"reference/js-bao-wss-client/api/interfaces/FunctionsAPI.md"}'),n={name:"reference/js-bao-wss-client/api/interfaces/FunctionsAPI.md"};function s(i,e,c,l,d,h){return r(),t("div",null,[...e[0]||(e[0]=[o('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / FunctionsAPI</p><h1 id="interface-functionsapi" tabindex="-1">Interface: FunctionsAPI <a class="header-anchor" href="#interface-functionsapi" aria-label="Permalink to “Interface: FunctionsAPI”">​</a></h1><p>Server functions, available as <code>client.functions</code>.</p><p>A function is TypeScript an app&#39;s team authored in its config tree and pushed with <code>primitive config push</code>. Invoking one runs it on the platform under the calling user&#39;s own authority and returns its result.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="claimapply" tabindex="-1">claimApply() <a class="header-anchor" href="#claimapply" aria-label="Permalink to “claimApply()”">​</a></h3><blockquote><p><strong>claimApply</strong>(<code>ref</code>): <code>Promise</code>&lt;<a href="./ClaimApplyResult.html"><code>ClaimApplyResult</code></a>&gt;</p></blockquote><p>Claim a function run&#39;s result for a client-side apply.</p><p>Kept for shape parity with workflow runs: a function run never enters the apply flow (nothing on this path produces a client-apply payload), so this answers the existing refusal rather than being absent. A caller writing one code path over both kinds of run gets the same envelope either way.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="ref" tabindex="-1">ref <a class="header-anchor" href="#ref" aria-label="Permalink to “ref”">​</a></h5><p><a href="./FunctionRunRef.html"><code>FunctionRunRef</code></a></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./ClaimApplyResult.html"><code>ClaimApplyResult</code></a>&gt;</p><hr><h3 id="confirmapply" tabindex="-1">confirmApply() <a class="header-anchor" href="#confirmapply" aria-label="Permalink to “confirmApply()”">​</a></h3><blockquote><p><strong>confirmApply</strong>(<code>ref</code>): <code>Promise</code>&lt;<a href="./ConfirmApplyResult.html"><code>ConfirmApplyResult</code></a>&gt;</p></blockquote><p>Confirm that a claimed apply has been written to the document.</p><p>Kept for shape parity with workflow runs; a function run has no client-apply step to confirm, so this answers the existing refusal.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="ref-1" tabindex="-1">ref <a class="header-anchor" href="#ref-1" aria-label="Permalink to “ref”">​</a></h5><p><a href="./FunctionRunRef.html"><code>FunctionRunRef</code></a></p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./ConfirmApplyResult.html"><code>ConfirmApplyResult</code></a>&gt;</p><hr><h3 id="getstatus" tabindex="-1">getStatus() <a class="header-anchor" href="#getstatus" aria-label="Permalink to “getStatus()”">​</a></h3><blockquote><p><strong>getStatus</strong>&lt;<code>TOutput</code>&gt;(<code>runId</code>): <code>Promise</code>&lt;<a href="./WorkflowStatusResult.html"><code>WorkflowStatusResult</code></a>&lt;<code>TOutput</code>&gt;&gt;</p></blockquote><p>The current status of a function run, by run id.</p><p>Same route and same envelope as a DSL run&#39;s — <code>workflows/runs/:runId/status</code> — because a function run IS a run row.</p><h4 id="type-parameters" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="toutput" tabindex="-1">TOutput <a class="header-anchor" href="#toutput" aria-label="Permalink to “TOutput”">​</a></h5><p><code>TOutput</code> = <code>unknown</code></p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="runid" tabindex="-1">runId <a class="header-anchor" href="#runid" aria-label="Permalink to “runId”">​</a></h5><p><code>string</code></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./WorkflowStatusResult.html"><code>WorkflowStatusResult</code></a>&lt;<code>TOutput</code>&gt;&gt;</p><hr><h3 id="invoke" tabindex="-1">invoke() <a class="header-anchor" href="#invoke" aria-label="Permalink to “invoke()”">​</a></h3><blockquote><p><strong>invoke</strong>&lt;<code>TOutput</code>, <code>TInput</code>&gt;(<code>functionKey</code>, <code>options?</code>): <code>Promise</code>&lt;<a href="./FunctionInvokeResult.html"><code>FunctionInvokeResult</code></a>&lt;<code>TOutput</code>&gt;&gt;</p></blockquote><p>Invoke a server function and wait for its result.</p><p><code>input</code> is named for what it is on this side of the wire; it travels as the envelope&#39;s <code>rootInput</code>, which is the field name the workflow surfaces already use.</p><h4 id="type-parameters-1" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters-1" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="toutput-1" tabindex="-1">TOutput <a class="header-anchor" href="#toutput-1" aria-label="Permalink to “TOutput”">​</a></h5><p><code>TOutput</code> = <code>unknown</code></p><h5 id="tinput" tabindex="-1">TInput <a class="header-anchor" href="#tinput" aria-label="Permalink to “TInput”">​</a></h5><p><code>TInput</code> = <code>unknown</code></p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="functionkey" tabindex="-1">functionKey <a class="header-anchor" href="#functionkey" aria-label="Permalink to “functionKey”">​</a></h5><p><code>string</code></p><h5 id="options" tabindex="-1">options? <a class="header-anchor" href="#options" aria-label="Permalink to “options?”">​</a></h5><p><a href="./FunctionInvokeOptions.html"><code>FunctionInvokeOptions</code></a>&lt;<code>TInput</code>&gt; = <code>{}</code></p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./FunctionInvokeResult.html"><code>FunctionInvokeResult</code></a>&lt;<code>TOutput</code>&gt;&gt;</p><hr><h3 id="releaseapply" tabindex="-1">releaseApply() <a class="header-anchor" href="#releaseapply" aria-label="Permalink to “releaseApply()”">​</a></h3><blockquote><p><strong>releaseApply</strong>(<code>ref</code>): <code>Promise</code>&lt;<a href="./ReleaseApplyResult.html"><code>ReleaseApplyResult</code></a>&gt;</p></blockquote><p>Release a claimed apply so another client can retry it.</p><p>Kept for shape parity with workflow runs; a function run has no client-apply step to release, so this answers the existing refusal.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="ref-2" tabindex="-1">ref <a class="header-anchor" href="#ref-2" aria-label="Permalink to “ref”">​</a></h5><p><a href="./FunctionRunRef.html"><code>FunctionRunRef</code></a></p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./ReleaseApplyResult.html"><code>ReleaseApplyResult</code></a>&gt;</p><hr><h3 id="start" tabindex="-1">start() <a class="header-anchor" href="#start" aria-label="Permalink to “start()”">​</a></h3><blockquote><p><strong>start</strong>&lt;<code>TInput</code>&gt;(<code>functionKey</code>, <code>options?</code>): <code>Promise</code>&lt;<a href="./FunctionStartResult.html"><code>FunctionStartResult</code></a>&gt;</p></blockquote><p>Start a DURABLE server function and get its run id back.</p><p>The run is polled on exactly the routes a DSL workflow run is, which is why the methods below are aliases rather than a parallel protocol.</p><p><code>runKey</code> makes the start idempotent per <code>(caller, contextDocId, runKey)</code>: a repeat answers the run that already exists with <code>existing: true</code>, never a second run. There is no <code>forceRerun</code> on this route.</p><h4 id="type-parameters-2" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters-2" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="tinput-1" tabindex="-1">TInput <a class="header-anchor" href="#tinput-1" aria-label="Permalink to “TInput”">​</a></h5><p><code>TInput</code> = <code>unknown</code></p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="functionkey-1" tabindex="-1">functionKey <a class="header-anchor" href="#functionkey-1" aria-label="Permalink to “functionKey”">​</a></h5><p><code>string</code></p><h5 id="options-1" tabindex="-1">options? <a class="header-anchor" href="#options-1" aria-label="Permalink to “options?”">​</a></h5><p><a href="./FunctionStartOptions.html"><code>FunctionStartOptions</code></a>&lt;<code>TInput</code>&gt; = <code>{}</code></p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./FunctionStartResult.html"><code>FunctionStartResult</code></a>&gt;</p><hr><h3 id="terminate" tabindex="-1">terminate() <a class="header-anchor" href="#terminate" aria-label="Permalink to “terminate()”">​</a></h3><blockquote><p><strong>terminate</strong>&lt;<code>TOutput</code>&gt;(<code>ref</code>): <code>Promise</code>&lt;<a href="./WorkflowStatusResult.html"><code>WorkflowStatusResult</code></a>&lt;<code>TOutput</code>&gt;&gt;</p></blockquote><p>Terminate a running function run.</p><h4 id="type-parameters-3" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters-3" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="toutput-2" tabindex="-1">TOutput <a class="header-anchor" href="#toutput-2" aria-label="Permalink to “TOutput”">​</a></h5><p><code>TOutput</code> = <code>unknown</code></p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="ref-3" tabindex="-1">ref <a class="header-anchor" href="#ref-3" aria-label="Permalink to “ref”">​</a></h5><p><a href="./FunctionRunRef.html"><code>FunctionRunRef</code></a></p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./WorkflowStatusResult.html"><code>WorkflowStatusResult</code></a>&lt;<code>TOutput</code>&gt;&gt;</p><hr><h3 id="waitfor" tabindex="-1">waitFor() <a class="header-anchor" href="#waitfor" aria-label="Permalink to “waitFor()”">​</a></h3><blockquote><p><strong>waitFor</strong>&lt;<code>TOutput</code>&gt;(<code>runId</code>, <code>options?</code>): <code>Promise</code>&lt;<a href="./WaitForWorkflowResult.html"><code>WaitForWorkflowResult</code></a> &amp; <code>object</code>&gt;</p></blockquote><p>Wait for a function run to reach a terminal state.</p><p>POLLS, where <code>workflows.waitFor</code> waits on a <code>workflowStatus</code> frame. That is not a stylistic difference: a function run broadcasts nothing over the WebSocket (D-3 — the contract for criterion 2 is poll-based), so a delegate to the workflow method would reconcile once, see <code>running</code>, and then wait out its whole <code>timeoutMs</code> with nothing left to wake it. Every other method on this class IS an alias; this one cannot be.</p><p>The interval starts short and backs off, so a function that finishes in a second is not waited out and one that sleeps for an hour is not polled thousands of times.</p><h4 id="type-parameters-4" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters-4" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="toutput-3" tabindex="-1">TOutput <a class="header-anchor" href="#toutput-3" aria-label="Permalink to “TOutput”">​</a></h5><p><code>TOutput</code> = <code>unknown</code></p><h4 id="parameters-7" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-7" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="runid-1" tabindex="-1">runId <a class="header-anchor" href="#runid-1" aria-label="Permalink to “runId”">​</a></h5><p><code>string</code></p><h5 id="options-2" tabindex="-1">options? <a class="header-anchor" href="#options-2" aria-label="Permalink to “options?”">​</a></h5><p><a href="./WaitForWorkflowOptions.html"><code>WaitForWorkflowOptions</code></a></p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./WaitForWorkflowResult.html"><code>WaitForWorkflowResult</code></a> &amp; <code>object</code>&gt;</p>',110)])])}const f=a(n,[["render",s]]);export{u as __pageData,f as default};
